package com.littlemakers.village.rendercheck;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;
/** Runs on an isolated emulator; exercises real renderer-driven walking and the existing UI handlers. */
public final class AdventureCheck extends Instrumentation {
 private Activity activity;private File output;private int passed;
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private Object call(Object o,String n,Class<?>[]t,Object...a)throws Exception{Method m=o.getClass().getDeclaredMethod(n,t);m.setAccessible(true);return m.invoke(o,a);}
 private void ui(Runnable r){java.util.concurrent.atomic.AtomicReference<Throwable>failure=new java.util.concurrent.atomic.AtomicReference<>();runOnMainSync(()->{try{r.run();}catch(Throwable e){failure.set(e);}});waitForIdleSync();if(failure.get()!=null)throw new AssertionError("UI operation failed",failure.get());}
 private void waitFor(Condition c,String label)throws Exception{long end=SystemClock.uptimeMillis()+30000;while(SystemClock.uptimeMillis()<end){if(c.ok())return;SystemClock.sleep(100);}throw new AssertionError("Timed out: "+label);}
 private interface Condition{boolean ok()throws Exception;}
 private Button find(View v,String text){if(v instanceof Button&&text.equals(((Button)v).getText().toString()))return(Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=find(((ViewGroup)v).getChildAt(i),text);if(b!=null)return b;}return null;}
 private View desc(View v,String label){if(v.getContentDescription()!=null&&label.contentEquals(v.getContentDescription()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=desc(((ViewGroup)v).getChildAt(i),label);if(found!=null)return found;}return null;}
 private void click(String label){ui(()->{View b=desc(activity.getWindow().getDecorView(),label);if(b==null)b=find(activity.getWindow().getDecorView(),label);if(b==null)throw new AssertionError("Missing control "+label);b.performClick();});}
 private void spot(int i){ui(()->{try{View water=(View)field(activity,"aquarium");if(!water.getAccessibilityNodeProvider().performAction(i,android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK,null))throw new AssertionError("Spot "+i);}catch(Exception e){throw new RuntimeException(e);}});}

 private void screen(String name)throws Exception{SystemClock.sleep(250);Materials38.visit(activity.getWindow().getDecorView());Bitmap b=getUiAutomation().takeScreenshot();if(b==null)throw new AssertionError("No screenshot");try(FileOutputStream f=new FileOutputStream(new File(output,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();passed++;Bundle status=new Bundle();status.putString("case",name);sendStatus(1,status);}
 @Override public void onStart(){Bundle result=new Bundle();try{
  output=new File(getTargetContext().getFilesDir(),"adventure-check");output.mkdirs();Intent i=new Intent().setClassName("com.littlemakers.village","com.littlemakers.village.nativeapp.AdventureActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=startActivitySync(i);waitForIdleSync();Object state=field(activity,"expedition"),wallet=field(activity,"wallet"),progress=field(activity,"progress");
  ui(()->{try{call(state,"reset",new Class[0]);call(activity,"show",new Class[]{String.class},"island");}catch(Exception e){throw new RuntimeException(e);}});
  waitFor(()->field(activity,"island")!=null&&((Long)field(field(activity,"island"),"renderedFrames"))>=2,"island meshes");screen("adventure-follow");
  int coins=(Integer)call(wallet,"coins",new Class[0]),stars=(Integer)call(wallet,"stars",new Class[0]);boolean rewarded=(Boolean)call(progress,"completed",new Class[]{String.class},"creative-adventure-0");
  for(int seed=1;seed<=3;seed++){final int expected=seed;ui(()->{try{call(field(activity,"island"),"clue",new Class[0]);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->((Integer)call(state,"nearSeed",new Class[0]))>=0,"walk to seed "+seed);ui(()->{try{((Button)field(activity,"action")).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->((Integer)call(state,"seeds",new Class[0]))==expected,"collect seed "+seed);}
  ui(()->{try{call(field(activity,"island"),"clue",new Class[0]);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->(Boolean)call(state,"nearBridge",new Class[0]),"walk to bridge");
  for(int part=1;part<=3;part++){final int expected=part;ui(()->{try{((Button)field(activity,"action")).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->((Integer)field(state,"bridge"))==expected,"grow bridge part "+part);}
  waitFor(()->(Integer)call(wallet,"coins",new Class[0])==coins+(rewarded?0:5),"central wallet reward");if((Integer)call(wallet,"stars",new Class[0])!=stars+(rewarded?0:1))throw new AssertionError("Star reward mismatch");if((Boolean)call(wallet,"creativeCompletion",new Class[]{String.class},"adventure-0"))throw new AssertionError("Replay reward duplicated");screen("adventure-bridge");
  ui(()->{try{call(activity,"show",new Class[]{String.class},"habitat");}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->field(activity,"aquarium")!=null&&((Long)field(field(activity,"aquarium"),"renderedFrames"))>=2,"aquarium meshes");
  spot(0);click("Water plant, Place");spot(1);click("Smooth rock, Place");spot(2);click("Garden arch, Place");Object habitat=field(activity,"habitat");if((Integer)call(habitat,"count",new Class[0])!=3)throw new AssertionError("Habitat placement failed");screen("adventure-aquarium");
  ActivityMonitor monitor=addMonitor("com.littlemakers.village.nativeapp.AdventureActivity",null,false);ui(()->activity.recreate());Activity restored=waitForMonitorWithTimeout(monitor,15000);removeMonitor(monitor);if(restored==null)throw new AssertionError("Activity recreation failed");activity=restored;waitForIdleSync();if((Integer)call(field(activity,"habitat"),"count",new Class[0])!=3||(Integer)field(field(activity,"expedition"),"bridge")!=3)throw new AssertionError("Adventure/layout did not persist");screen("adventure-restored");
  ui(()->{try{call(activity,"show",new Class[]{String.class},"album");}catch(Exception e){throw new RuntimeException(e);}});screen("adventure-album");
Activity hub=activity;
  ActivityMonitor creativeMonitor=addMonitor("com.littlemakers.village.nativeapp.CreativeActivity",null,false);ui(()->{try{call(activity,"learning",new Class[]{String.class},"paint");}catch(Exception e){throw new RuntimeException(e);}});Activity creative=waitForMonitorWithTimeout(creativeMonitor,15000);removeMonitor(creativeMonitor);if(creative==null||!"paint".equals(field(creative,"route")))throw new AssertionError("Learning doorway lost its destination");activity=creative;waitFor(()->field(activity,"creativeStage")!=null&&((Long)field(field(activity,"creativeStage"),"renderedFrames"))>0,"linked drawing studio");screen("adventure-linked-paint");ui(()->{try{call(activity,"returnToHub",new Class[0]);}catch(Exception e){throw new RuntimeException(e);}});activity=hub;waitForIdleSync();
  ActivityMonitor mainMonitor=addMonitor("com.littlemakers.village.nativeapp.MainActivity",null,false);ui(()->{try{call(activity,"legacy",new Class[]{String.class},"playroom");}catch(Exception e){throw new RuntimeException(e);}});Activity main=waitForMonitorWithTimeout(mainMonitor,15000);removeMonitor(mainMonitor);if(main==null||!main.getIntent().getBooleanExtra("adventure_return",false))throw new AssertionError("Game doorway lost hub return");activity=main;ui(()->{try{call(activity,"openGame",new Class[]{String.class,boolean.class},"native-maze-1",true);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->field(field(activity,"gameView"),"stage")!=null&&((Long)field(field(field(activity,"gameView"),"stage"),"renderedFrames"))>0,"linked native game");screen("adventure-linked-maze");ui(()->{try{call(activity,"home",new Class[0]);}catch(Exception e){throw new RuntimeException(e);}});activity=hub;waitForIdleSync();
    getTargetContext().getSharedPreferences("family",0).edit().putString("theme","dark").putBoolean("reduce_motion",true).commit();ui(()->{try{call(activity,"show",new Class[]{String.class},"island");}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->field(activity,"island")!=null&&((Long)field(field(activity,"island"),"renderedFrames"))>=1,"dark reduced island");screen("adventure-dark-reduced");ui(()->activity.onBackPressed());screen("adventure-break-dialog");sendKeyDownUpSync(android.view.KeyEvent.KEYCODE_BACK);getTargetContext().getSharedPreferences("family",0).edit().putString("theme","light").putBoolean("reduce_motion",false).commit();ui(()->activity.finish());result.putString("stream","PASS "+passed+" adventure screens; real guided walking, counting, bridge building, wallet idempotency, UI placement and recreation persistence\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("stream","FAIL after "+passed+": "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
